package com.app.entity; import jakarta.persistence.*; import lombok.*; import java.time.LocalDateTime;
@Entity @Table(name="society_notifications") @Data @Builder @NoArgsConstructor @AllArgsConstructor public class SocietyNotification {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="account_id",nullable=false) private Account account;@ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="recipient_user_id",nullable=false) private User recipient;@Column(nullable=false,length=40) private String notificationType;@Column(nullable=false,length=40) private String entityType;@Column(nullable=false) private Long entityId;@Column(nullable=false,length=160) private String dedupeKey;@Column(nullable=false,length=180) private String title;@Column(nullable=false,length=1000) private String message;@Column(nullable=false,length=20) @Builder.Default private String priority="NORMAL";private LocalDateTime readAt;@Column(nullable=false,updatable=false) @Builder.Default private LocalDateTime createdAt=LocalDateTime.now();}
